pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(bool _payRoyalties) public {
        vm.assume(_payRoyalties == true);
        address base = address(0x1);
        address nftAddr = address(0x2);
        c.initialize(base, nftAddr, 1, 1, 1, 100, bytes32(0), false, _payRoyalties);
        bool actual = c.payRoyalties();
        assertTrue(actual == true);
    }
}
